/// Music ids of a zone, if LandSandBoat has an entry for it.
pub fn zone_music(zone: u16) -> Option<(u16, u16, u16, u16)> {
    ZONE_MUSIC.iter().find(|r| r.0 == zone).map(|r| (r.1, r.2, r.3, r.4))
}

/// Track name of a music id.
pub fn music_name(id: u16) -> Option<&'static str> {
    MUSIC_NAMES.iter().find(|(i, _)| *i == id).map(|(_, n)| *n)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ronfaure() {
        assert_eq!(zone_music(100), Some((109, 109, 101, 103)));
        assert_eq!(zone_music(230).map(|m| m.0), Some(107));
        assert_eq!(music_name(109), Some("Ronfaure"));
    }
}
